// setAccountClientFailed records an AWS STS/client credential failure on the Account status,
// deriving the failure reason from the AWS error code when available.
func (r *AccountReconciler) setAccountClientFailed(reqLogger logr.Logger, currentAcctInstance *awsv1alpha1.Account, err error) {
	// Get custom failure reason to update account status
	reason := ""
	if aerr, ok := err.(awserr.Error); ok {
		reason = aerr.Code()
	}
	errMsg := fmt.Sprintf("Failed to create STS Credentials for account ID %s: %s", currentAcctInstance.Spec.AwsAccountID, err)
	_, stateErr := r.setAccountFailed(
		reqLogger,
		currentAcctInstance,
		awsv1alpha1.AccountClientError,
		reason,
		errMsg,
		AccountFailed,
	)
	if stateErr != nil {
		reqLogger.Error(stateErr, "failed setting account state", "desiredState", AccountFailed)
	}
}

